            "protocol": protocol,
            "accepted_count": accepted_count,
            "duplicate_count": len(receipts) - accepted_count,
        }
        if command == "accepted":
            result["receipts"] = [
                receipt for index, receipt in enumerate(receipts) if index in winner_indices
            ]
        return result
    return {"error": "unknown_command"}

